def main():
    ap=argparse.ArgumentParser(); ap.add_argument("--cache",type=Path,required=True); ap.add_argument("--out",type=Path,required=True); args=ap.parse_args(); out=args.out
    inv=[json.loads(x) for x in (out/"INVENTORY-ALL.jsonl").read_text(encoding="utf-8").splitlines()]
    activity=json.loads((out/"EVIDENCE/TARGET-ACTIVITY.json").read_text(encoding="utf-8")); act={x["repo"].lower():x for x in activity}
    reviews=[]; source_index=[]
    assert len(SPEC)==40 and len(EXTRA)==9
    for rank,line in list(enumerate(SPEC,1))+list(enumerate(EXTRA,42)):
        e=json.loads((args.cache/f"{rank}.json").read_text(encoding="utf-8")); license_scope,requirements,capability,risk,decision,acceptance=line.split("|")
        refs=[]
        for r in e["resources"]:
            body=r.get("data",{}).get("content")
            if body is None: continue
            b=body.encode(); blob=hashlib.sha1(b"blob "+str(len(b)).encode()+b"\0"+b).hexdigest()
            source_index.append(dict(repo=e["canonical_repo"],requested_repo=e["repo"],head=e["head"],kind=r["kind"],path=r["data"]["display_title"],url=r["url"],git_blob=r["data"]["sha"],computed_git_blob=blob,sha256=sha(b),bytes=len(b),checked_at=e["checked_at"]))
            assert blob==r["data"]["sha"], (rank,r["kind"])
            refs.append(dict(kind=r["kind"],url=r["url"],git_blob=blob,sha256=sha(b)))
        matched=[r["source_id"] for r in inv if r["entity_id"] in {"github:"+e["repo"].lower(),"github:"+e["canonical_repo"].lower()}]
        reviews.append(dict(rank=rank,repo=e["repo"],canonical_repo=e["canonical_repo"],need=e["need"],head=e["head"],source_ids=matched,archive_membership="EXACT_PROJECT_MATCH" if matched else "ARCHITECTURE_ADDITION_NOT_IN_ORIGINAL_PROJECT_URLS",documented_capability=capability,requirements=requirements,license_scope=license_scope,dependency_licenses="NOT_AUDITED",cost="License scope above; model/API/hosting and EE charges separate; actual AWE cost NOT_MEASURED",risk=risk,integration_type=requirements.split(";")[0],decision=decision,minimum_acceptance=acceptance,evidence_refs=refs,activity=act.get(e["canonical_repo"].lower()),technical_status="SOURCE_LINKED_DESK_REVIEW",runtime="NOT_RUN",security_audit="NOT_PERFORMED",awe_acceptance="NOT_PROVEN",approved=False))
    reviews.append(dict(rank=41,repo=None,canonical_repo=None,need="official_figma",head=None,source_ids=[],archive_membership="ARCHITECTURE_ADDITION",documented_capability="Official remote MCP documents design context, native canvas writes and code-to-canvas workflows",requirements="Compatible remote MCP client and file permissions; Full seat for writes outside drafts",license_scope="Hosted service terms, not an OSS grant",cost="Write beta currently free; docs say future usage charging. Existing plan/access not checked",risk="Beta/plan/client constraints; actual AWE connection and visual correctness unproven",integration_type="REMOTE_MCP",decision="PILOT",minimum_acceptance="Disposable draft: read design context, make one authorized write, independent screenshot/token/layout QA and exact file rollback",evidence_refs=[dict(kind="official_documentation",url="https://developers.figma.com/docs/figma-mcp-server/",checked_at="2026-11-12")],technical_status="OFFICIAL_DOC_DESK_REVIEW",runtime="NOT_RUN",security_audit="NOT_PERFORMED",awe_acceptance="NOT_PROVEN",approved=False))
    reviews.sort(key=lambda r:r["rank"])
    dump(out/"TECHNICAL-REVIEWS.json",reviews); dump(out/"EVIDENCE/PRIMARY-SOURCE-INDEX.json",source_index)
    code=json.loads((args.cache.parent/"CODE-INSPECTION.json").read_text(encoding="utf-8")); code_index=[]
    for x in code:
        body=x.get("data",{}).get("content")
        code_index.append(dict(repo=x["repo"],head=x["head"],path=x["path"],git_blob=x.get("data",{}).get("sha"),sha256=sha(body.encode()) if body else None,status="SOURCE_FILE_READ" if body else "NOT_FOUND",url=f"https://github.com/{x['repo']}/blob/{x['head']}/{x['path']}"))
    dump(out/"EVIDENCE/CODE-SOURCE-INDEX.json",code_index)
    lines=["# Приоритетные технологии: 50 технических desk reviews", "", "**PARTIAL.** 49 репозиториев + официальный Figma MCP. Это анализ документации/лицензий с ограниченным чтением кода, не 50 runtime/security-аудитов. Для добавленных 9 репозиториев даты релизов отдельно не исследованы; pinned HEAD/README/LICENSE и repository metadata сохранены.", "", "Для всех решений: установки и upstream code execution не выполнялись; AWE acceptance NOT_PROVEN, APPROVED=0. REUSE означает рекомендацию использовать существующий компонент после проверок, а не допуск в runtime. Cross-family QA NOT_SATISFIED. Кандидаты вне исходных URL архива явно помечены.", ""]
    for r in reviews:
        name=r["canonical_repo"] or "Официальный Figma MCP"
        lines.extend([f"## {r['rank']}. {name}","",f"**Решение: {r['decision']}.** {r['documented_capability']}","",f"Привязка к архиву: {', '.join(r['source_ids']) or r['archive_membership']}. Версия: `{r['head'] or 'hosted docs 2026-11-12'}`.","",f"Подключение и требования: {r['requirements']}.","",f"Лицензия: {r['license_scope']}. Транзитивные зависимости не аудированы. {r['cost']}.","",f"Ограничение: {r['risk']}.","",f"Минимальная приёмка: {r['minimum_acceptance']}.","", "Источники: "+", ".join(f"[{s['kind']}]({s['url']})" for s in r["evidence_refs"])+".",""])
        if r.get("activity"):
            a=r["activity"]; rel=a["latest_release"]
            lines.extend([f"Активность: commit date `{a.get('commit_date')}`; последний наблюдаемый релиз `{rel.get('tag','NOT_OBSERVED')}` ({rel.get('published_at','UNKNOWN')}). Релизный бинарник не проверялся.",""])
    (out/"TOP-50-DEEP-REVIEW.md").write_text("\n".join(lines),encoding="utf-8")
    print(json.dumps(dict(reviews=len(reviews),primary_documents=len(source_index),code_files_read=sum(x["status"]=="SOURCE_FILE_READ" for x in code_index),archive_rows_with_project_match=len({i for r in reviews for i in r["source_ids"]})),ensure_ascii=False))

if __name__=="__main__": main()
